/* The galaxy as it starts: src/galaxy_data.c, generated by tools/galaxy/gen.py (M16a). */
extern const StarSystem galaxy_start[GALAXY_SYSTEMS];
#define start_systems galaxy_start

static const char *band_names[BAND_COUNT]   = { "CORE", "MID BELT", "FRONTIER", "OUTER RIM" };
static StarSystem systems[GALAXY_SYSTEMS];   /* owners change (M14g): reset from start_systems */
static const char *owner_names[OWN_COUNT]   = { "UFS", "INDEPENDENT", "FSA", "OUTER RIM SYNDICATES", "YOU", "NOBODY: EMPTY SPACE", "THE VEYR" };
static const char *security_names[4]        = { "VERY LOW", "LOW", "MEDIUM", "HIGH" };
static const char *econ_names[ECON_COUNT]   = {
    "AGRICULTURAL", "INDUSTRIAL", "MINING", "MILITARY", "SETTLEMENT", "TRADE HUB"
};

static int current, route_dest = -1;

const StarSystem *galaxy_sys(int id) {
    if (!systems[0].name) memcpy(systems, start_systems, sizeof systems);   /* before the first galaxy_init */
    return &systems[id];
}
int galaxy_current(void) { return current; }
const char *galaxy_security_name(int level) { return security_names[level & 3]; }
const char *galaxy_econ_name(int econ) { return econ_names[econ]; }

static u8 known[GALAXY_SYSTEMS];

int galaxy_known(int id) { return known[id]; }
int galaxy_empty(int id) { return systems[id].station_name == 0; }
void galaxy_mark_known(int id) { known[id] = 1; }

void galaxy_set_owner(int id, int owner) { if (id >= 0 && id < GALAXY_SYSTEMS) systems[id].owner = (u8) owner; }
int galaxy_founder(int id) { return start_systems[id].owner; }
int galaxy_owned_count(int owner) {
    int n = 0;
    for (int i = 0; i < GALAXY_SYSTEMS; i++) if (systems[i].owner == owner) n++;
    return n;
}

u8 *galaxy_ser(u8 *p, int load) {
    u8 own[GALAXY_SYSTEMS];
    for (int i = 0; i < GALAXY_SYSTEMS; i++) own[i] = systems[i].owner;
    SER(p, load, current); SER(p, load, route_dest); SER(p, load, known);
    if (!load || ser_version >= 5) SER(p, load, own);   /* owners: M14g saves on */
    if (load) for (int i = 0; i < GALAXY_SYSTEMS; i++) systems[i].owner = own[i] < OWN_COUNT ? own[i] : start_systems[i].owner;
    return p;
}

/* On the map: charted systems, plus the uncharted ones linked to where you are
 * (so a single blind jump is always possible). */
static int nebula_open;      /* the Veyr nebula's links are open (M17a) */
static int visible(int id) { return (known[id] && (!systems[id].hidden || nebula_open)) || galaxy_link_index(current, id) >= 0; }

int galaxy_chart(void) {
    int fresh = 0;
    for (int i = 0; i < GALAXY_SYSTEMS; i++)
        if (!known[i] && !systems[i].hidden && galaxy_dist(current, i) <= CHART_RADIUS) { known[i] = 1; fresh++; }
    return fresh;
}

void galaxy_init(void) {
    memcpy(systems, start_systems, sizeof systems);
    for (int i = 0; i < GALAXY_SYSTEMS; i++) known[i] = 0;
    nebula_open = 0;
    route_dest = -1;
    galaxy_enter(0);
}

void galaxy_enter(int id) {
    current = id;
    known[id] = 1;
    world_set_system(id);
}

/* A link into the Veyr nebula is closed until the hive has been found (M17a). */
static int link_open(int a, int b) { return nebula_open || (!systems[a].hidden && !systems[b].hidden); }
void galaxy_open_nebula(int open) { nebula_open = open; }
int  galaxy_nebula_open(void) { return nebula_open; }
int  galaxy_port_open(int id) { return systems[id].station_name != 0 && systems[id].owner != OWN_VEYR; }

int galaxy_link_index(int from, int to) {
    for (int i = 0; i < systems[from].njumps; i++)
        if (systems[from].link[i] == to) return link_open(from, to) ? i : -1;
    return -1;
}

int galaxy_dist(int a, int b) {
    return (int) approx_len(systems[a].map_x - systems[b].map_x, systems[a].map_y - systems[b].map_y);
}

int galaxy_jump_fuel(int a, int b)  { return 1 + galaxy_dist(a, b) / 10; }
int galaxy_jump_hours(int a, int b) { int h = galaxy_dist(a, b) / 2; return h < 4 ? 4 : h; }   /* M16a: the galaxy is bigger, jumps quicker */

/* ------------------------------------------------------------------------ */
/* Routes: breadth-first search over the links                               */
/* ------------------------------------------------------------------------ */

void galaxy_set_route(int dest) { route_dest = dest; }
int  galaxy_route(void) { return route_dest; }

/* Hops from every system to dest (-1 = unreachable). */
static void hops_to(int dest, int *d) {
    int queue[GALAXY_SYSTEMS], head = 0, tail = 0;
    for (int i = 0; i < GALAXY_SYSTEMS; i++) d[i] = -1;
    d[dest] = 0;
    queue[tail++] = dest;
    while (head < tail) {
        int x = queue[head++];
        for (int j = 0; j < systems[x].njumps; j++) {
            int n = systems[x].link[j];
            if (d[n] < 0 && link_open(x, n)) { d[n] = d[x] + 1; queue[tail++] = n; }
        }
    }
}

int galaxy_next_hop(int from, int dest) {
    if (from == dest) return -1;
    int d[GALAXY_SYSTEMS];
    hops_to(dest, d);
    if (d[from] < 0) return -1;
    for (int j = 0; j < systems[from].njumps; j++) {
        int n = systems[from].link[j];
        if (d[n] == d[from] - 1 && link_open(from, n)) return n;
    }
    return -1;
}

int galaxy_route_hops(int from, int dest) {
    int d[GALAXY_SYSTEMS];
    hops_to(dest, d);
    return d[from];
}

/* Another system 1..max_hops jumps from `from` (with a port if need_port): for
 * missions and lounge talk, so nothing sends you across the whole galaxy (M16a). */
int galaxy_random_near(int from, int max_hops, int need_port) {
    int d[GALAXY_SYSTEMS], pick[GALAXY_SYSTEMS], n = 0;
    hops_to(from, d);
    for (int i = 0; i < GALAXY_SYSTEMS; i++)
        if (d[i] >= 1 && d[i] <= max_hops && (!need_port || galaxy_port_open(i))) pick[n++] = i;
    return n ? pick[rng_range(n)] : -1;
}

int galaxy_route_fuel(int from, int dest) {
    int total = 0, at = from, guard = GALAXY_SYSTEMS;
    while (at != dest && guard-- > 0) {
        int n = galaxy_next_hop(at, dest);
        if (n < 0) return -1;
        total += galaxy_jump_fuel(at, n);
        at = n;
    }
    return at == dest ? total : -1;
}

/* ------------------------------------------------------------------------ */
/* The galaxy map screen                                                     */
/* ------------------------------------------------------------------------ */

#define PANEL_X 16
#define PANEL_Y 16
#define PANEL_W 608
#define PANEL_H 448
#define MAP_X0  60            /* map area: 0..100 maps onto this box */
#define MAP_Y0  120
#define MAP_W   330
#define MAP_H   250            /* leaves room for the legend under the map */

/* The map view (M16a): the galaxy is 400 x 240 units, seen through a window that
 * pans to the selected system. Three zooms: the whole galaxy (just the stars),
 * the region (names), close up (names, owner, security, your squadrons). */
#define VIEW_X0 50
#define VIEW_X1 392
#define VIEW_Y0 108
#define VIEW_Y1 380
#define VIEW_CX ((VIEW_X0 + VIEW_X1) / 2)
#define VIEW_CY ((VIEW_Y0 + VIEW_Y1) / 2)
#define ZOOMS 3
static int zoom_scale[ZOOMS] = { 13, 32, 56 };          /* pixels per 16 map units */
static int zoom = 1;
static s32 cam_x16, cam_y16;                            /* the view's centre, map units x16 */

static int map_open, sel, anim, msg_timer;
static char msg[48];

static void say(const char *t) {
    strncpy(msg, t, sizeof msg - 1);
    msg[sizeof msg - 1] = 0;
    msg_timer = 150;
}

void galaxy_map_open(void) {
    map_open = 1;
    sel = current;
    msg_timer = 0;
    cam_x16 = systems[sel].map_x * 16;
    cam_y16 = systems[sel].map_y * 16;
}

static int visible(int id);

/* The next system on the map in a D-pad direction: ahead of the selection, and
 * as straight ahead as possible. */
static int pick_toward(int dx, int dy) {
    int best = -1, best_score = 0x7fffffff;
    for (int i = 0; i < GALAXY_SYSTEMS; i++) {
        if (i == sel || !visible(i)) continue;
        int vx = systems[i].map_x - systems[sel].map_x, vy = systems[i].map_y - systems[sel].map_y;
        int along = vx * dx + vy * dy;
        if (along <= 0) continue;
        int perp = vx * dy - vy * dx; if (perp < 0) perp = -perp;
        int score = along + perp * 2;
        if (score < best_score) { best_score = score; best = i; }
    }
    return best;
}

int galaxy_map_active(void) { return map_open; }

int galaxy_map_update(void) {
    anim++;
    audio_menu();
    if (msg_timer > 0) msg_timer--;

    {
        int dx = input_pressed(PAD_RIGHT) ? 1 : input_pressed(PAD_LEFT) ? -1 : 0;
        int dy = input_pressed(PAD_DOWN) ? 1 : input_pressed(PAD_UP) ? -1 : 0;
        if (dx || dy) { int n = pick_toward(dx, dy); if (n >= 0) sel = n; }
    }
    zoom_scale[0] = nebula_open ? 11 : 13;               /* the whole galaxy, nebula and all */
    if (input_pressed(PAD_R1) && zoom < ZOOMS - 1) zoom++;
    if (input_pressed(PAD_L1) && zoom > 0) zoom--;
    if (input_pressed(PAD_TRIANGLE)) sel = current;
    {   /* the view glides to the selection (the whole galaxy stays centred) */
        s32 tx = zoom == 0 ? (nebula_open ? 240 : 200) * 16 : systems[sel].map_x * 16, ty = zoom == 0 ? 120 * 16 : systems[sel].map_y * 16;
        cam_x16 += (tx - cam_x16) / 4;
        cam_y16 += (ty - cam_y16) / 4;
    }

    if (input_pressed(PAD_SQUARE)) {
        route_dest = -1;
        say("COURSE CLEARED");
        return GMAP_CLEARED;
    }
    if (input_pressed(PAD_CROSS)) {
        if (sel == current)                          say("YOU ARE ALREADY HERE");
        else if (galaxy_next_hop(current, sel) < 0)  say("NO KNOWN ROUTE");
        else { route_dest = sel; map_open = 0; return GMAP_PLOTTED; }
    }
    if (input_pressed(PAD_CIRCLE | PAD_SELECT)) map_open = 0;
    return GMAP_NONE;
}

static int node_x(int i) { return VIEW_CX + (int) ((systems[i].map_x * 16 - cam_x16) * zoom_scale[zoom] / 256); }
static int node_y(int i) { return VIEW_CY + (int) ((systems[i].map_y * 16 - cam_y16) * zoom_scale[zoom] / 256); }
static int in_view(int x, int y, int m) { return x >= VIEW_X0 + m && x <= VIEW_X1 - m && y >= VIEW_Y0 + m && y <= VIEW_Y1 - m; }

/* Cuts a line to the view (Cohen-Sutherland). 0 if none of it shows. */
static int clip_line(int *x0, int *y0, int *x1, int *y1) {
    for (int guard = 0; guard < 8; guard++) {
        int c0 = (*x0 < VIEW_X0) | (*x0 > VIEW_X1) << 1 | (*y0 < VIEW_Y0) << 2 | (*y0 > VIEW_Y1) << 3;
        int c1 = (*x1 < VIEW_X0) | (*x1 > VIEW_X1) << 1 | (*y1 < VIEW_Y0) << 2 | (*y1 > VIEW_Y1) << 3;
        if (!(c0 | c1)) return 1;
        if (c0 & c1) return 0;
        int c = c0 ? c0 : c1, x, y;
        int dx = *x1 - *x0, dy = *y1 - *y0;
        if (c & 1)      { x = VIEW_X0; y = *y0 + dy * (VIEW_X0 - *x0) / (dx ? dx : 1); }
        else if (c & 2) { x = VIEW_X1; y = *y0 + dy * (VIEW_X1 - *x0) / (dx ? dx : 1); }
        else if (c & 4) { y = VIEW_Y0; x = *x0 + dx * (VIEW_Y0 - *y0) / (dy ? dy : 1); }
        else            { y = VIEW_Y1; x = *x0 + dx * (VIEW_Y1 - *y0) / (dy ? dy : 1); }
        if (c == c0) { *x0 = x; *y0 = y; } else { *x1 = x; *y1 = y; }
    }
    return 0;
}

/* A line two-and-a-bit pixels thick, as a thin quad (a one-pixel line would
 * flicker in the interlaced display). */
static void thick_line(int x0, int y0, int x1, int y1, int z, int r, int g, int b) {
    int dx = x1 - x0, dy = y1 - y0;
    int len = (int) approx_len(dx, dy);
    if (len < 1) return;
    int nx = -dy * 2 / len, ny = dx * 2 / len;      /* half-width of 2 pixels */
    POLY_F4 *q = (POLY_F4 *) gfx_prim(z, sizeof(POLY_F4));
    if (!q) return;
    setPolyF4(q);
    setXY4(q, x0 - nx, y0 - ny, x0 + nx, y0 + ny, x1 - nx, y1 - ny, x1 + nx, y1 + ny);
    setRGB0(q, r, g, b);
}

static void map_line(int a, int b2, int r, int g, int b) {
    int x0 = node_x(a), y0 = node_y(a), x1 = node_x(b2), y1 = node_y(b2);
    if (clip_line(&x0, &y0, &x1, &y1)) thick_line(x0, y0, x1, y1, 0, r, g, b);
}

static void owner_colour(int owner, int *r, int *g, int *b) {
    switch (owner) {
    case OWN_FEDERATION:  *r = 90;  *g = 170; *b = 255; break;
    case OWN_INDEPENDENT: *r = 120; *g = 230; *b = 140; break;
    case OWN_REBEL:       *r = 230; *g = 80;  *b = 210; break;   /* FSA magenta, as in flight */
    case OWN_PLAYER:      *r = 255; *g = 205; *b = 60;  break;   /* yours: gold */
    case OWN_NONE:        *r = 120; *g = 120; *b = 130; break;   /* empty space: grey */
    case OWN_VEYR:        *r = 150; *g = 230; *b = 50;  break;   /* the Veyr: a sick green */
    default:              *r = 255; *g = 90;  *b = 90;  break;
    }
}

static void text(int x, int y, int scale, int r, int g, int b, const char *s) {
    gfx_text_big(x, y, 0, scale, r, g, b, s);
}

void galaxy_map_draw(void) {
    char line[64];

    /* Text and shapes first; the panel is added last, on a layer behind. */
    text(PANEL_X + 28, PANEL_Y + 18, 3, 90, 220, 255, "GALAXY MAP");
    snprintf(line, sizeof line, "YOU ARE IN %s    FUEL %d/%d", systems[current].name, fuel, fuel_max);
    text(PANEL_X + 28, PANEL_Y + 52, 1, 255, 230, 80, line);

    /* Info card for the selected system. */
    const StarSystem *s = &systems[sel];
    const int card_x = 408, card_y = 100, card_w = 188, card_h = 304;
    int ix = card_x + 12, iy = card_y + 10;
    int r, g, b;
    owner_colour(s->owner, &r, &g, &b);
    if (!known[sel]) {
        text(ix, iy, 2, 150, 155, 170, "UNCHARTED");                      iy += 28;
        text(ix, iy, 1, 170, 190, 215, "NO CHART DATA.");                 iy += 14;
        text(ix, iy, 1, 170, 190, 215, "A LINKED SYSTEM: YOU");           iy += 12;
        text(ix, iy, 1, 170, 190, 215, "CAN JUMP THERE BLIND.");          iy += 12;
        text(ix, iy, 1, 170, 190, 215, "CHARTS: TRADING POST");           iy += 12;
        text(ix, iy, 1, 170, 190, 215, "(SELECT, 500 CR).");              iy += 22;
        goto route_info;
    }
    text(ix, iy, 2, r, g, b, s->name);                                    iy += 28;
    snprintf(line, sizeof line, "%s", band_names[s->band]);
    text(ix, iy, 1, 230, 235, 245, line);                                 iy += 14;
    text(ix, iy, 1, 150, 170, 200, "OWNER");                              iy += 12;
    if (s->owner == OWN_PLAYER) {                                          /* M14g */
        snprintf(line, sizeof line, "YOU: %d CR/DAY", conquest_tribute_of(sel));
        text(ix, iy, 1, r, g, b, line);
    } else text(ix, iy, 1, r, g, b, owner_names[s->owner]);
    iy += 16;
    snprintf(line, sizeof line, "SECURITY %s", security_names[s->security & 3]);
    text(ix, iy, 1, 230, 235, 245, line);                                 iy += 14;
    if (galaxy_empty(sel)) {                                               /* M16a */
        text(ix, iy, 1, 255, 150, 100, "NO PLANET, NO PORT.");             iy += 14;
        text(ix, iy, 1, 255, 150, 100, "NO FUEL. AMBUSHES.");             iy += 24;
    } else {
        snprintf(line, sizeof line, "STATION %s", econ_names[s->econ[0]]);
        text(ix, iy, 1, 170, 190, 215, line);                             iy += 14;
        snprintf(line, sizeof line, "PLANET  %s", econ_names[s->econ[1]]);
        text(ix, iy, 1, 170, 190, 215, line);                             iy += 24;
    }

route_info:
    if (sel == current) {
        text(ix, iy, 1, 120, 220, 160, "YOU ARE HERE");
    } else {
        int hops = galaxy_route_hops(current, sel);
        int cost = galaxy_route_fuel(current, sel);
        if (hops < 0) {
            text(ix, iy, 1, 255, 120, 100, "NO KNOWN ROUTE");
        } else {
            snprintf(line, sizeof line, "%d JUMP%s", hops, hops == 1 ? "" : "S");
            text(ix, iy, 1, 230, 235, 245, line);                         iy += 14;
            snprintf(line, sizeof line, "FUEL NEEDED %d", cost);
            text(ix, iy, 1, cost <= fuel ? 120 : 255, cost <= fuel ? 220 : 120, cost <= fuel ? 160 : 100, line);
            iy += 14;
            /* Travel time: sum of the hops, in game days. */
            int hours = 0, at = current, guard = GALAXY_SYSTEMS;
            while (at != sel && guard-- > 0) {
                int n = galaxy_next_hop(at, sel);
                if (n < 0) break;
                hours += galaxy_jump_hours(at, n);
                at = n;
            }
            snprintf(line, sizeof line, "ABOUT %d DAYS", (hours + 12) / 24);
            text(ix, iy, 1, 230, 235, 245, line);
        }
    }

    /* Action buttons at the foot of the card (the pad keys shown on each). */
    {
        int can_plot = sel != current && galaxy_next_hop(current, sel) >= 0;
        int by = card_y + card_h - 84;
        gfx_button(ix - 2, by,      card_w - 20, 22, 0, can_plot ? BTN_SELECTED : BTN_DISABLED, 1, "X   PLOT COURSE");
        gfx_button(ix - 2, by + 26, card_w - 20, 22, 0, route_dest >= 0 ? BTN_NORMAL : BTN_DISABLED, 1, "SQ  CLEAR COURSE");
        gfx_button(ix - 2, by + 52, card_w - 20, 22, 0, BTN_NORMAL, 1, "O   CLOSE MAP");
    }
    gfx_card(card_x, card_y, card_w, card_h, 0);

    /* Legend under the map. */
    {
        static const char *who[OWN_COUNT] = { "UFS", "INDEP", "FSA", "RIM", "YOU", "EMPTY", "VEYR" };
        int lx = MAP_X0 - 8, ly = MAP_Y0 + MAP_H + 20;
        for (int o = 0; o < OWN_COUNT; o++) {
            int lr, lg, lb;
            owner_colour(o, &lr, &lg, &lb);
            gfx_rect(lx, ly, 8, 8, 0, lr, lg, lb);
            text(lx + 12, ly, 1, 170, 190, 215, who[o]);
            lx += 12 + (int) strlen(who[o]) * 8 + 4;
        }
    }

    if (route_dest >= 0) {
        snprintf(line, sizeof line, "COURSE SET TO %s", known[route_dest] ? systems[route_dest].name : "AN UNCHARTED SYSTEM");
        text(PANEL_X + 28, PANEL_Y + PANEL_H - 50, 1, 255, 230, 80, line);
    }
    if (msg_timer > 0) text(PANEL_X + 28, PANEL_Y + PANEL_H - 38, 1, 255, 200, 90, msg);
    text(PANEL_X + 28, PANEL_Y + PANEL_H - 26, 1, 150, 160, 180,
         "D-PAD: CHOOSE  L1 R1: ZOOM  TRIANGLE: YOU  X: PLOT COURSE");
    {
        static const char *zn[ZOOMS] = { "ZOOM: GALAXY", "ZOOM: REGION", "ZOOM: CLOSE" };
        text(VIEW_X1 - 100, VIEW_Y0 - 2, 1, 120, 140, 170, zn[zoom]);
    }

    /* Systems, selection and "you are here" markers (foreground first). */
    for (int i = 0; i < GALAXY_SYSTEMS; i++) {
        if (!visible(i)) continue;
        int x = node_x(i), y = node_y(i);
        if (!in_view(x, y, 3)) continue;
        int nr, ng, nb;
        owner_colour(systems[i].owner, &nr, &ng, &nb);
        if (!known[i]) { nr = ng = nb = 110; }
        const char *label = known[i] ? systems[i].name : "?";
        int len = (int) strlen(label);
        int lx = x - len * 4;
        if (lx < VIEW_X0) lx = VIEW_X0;
        if (lx + len * 8 > VIEW_X1) lx = VIEW_X1 - len * 8;
        /* Zoomed out: only the stars (and the names you need). Closer: names; closest: the details. */
        if ((zoom >= 1 || i == sel || i == current) && y + 20 <= VIEW_Y1)
            text(lx, y + 10, 1, i == sel ? 255 : 200, i == sel ? 230 : 205, i == sel ? 80 : 215, label);
        if (zoom >= 2 && known[i] && y + 31 <= VIEW_Y1) {
            static const char *own_short[OWN_COUNT] = { "UFS", "INDEP", "FSA", "SYNDICATE", "YOURS", "EMPTY", "VEYR" };
            static const char *sec_short[4] = { "LAWLESS", "LOW SEC", "MED SEC", "HIGH SEC" };
            char sub[32];
            if (galaxy_empty(i)) snprintf(sub, sizeof sub, "EMPTY, NO FUEL");
            else snprintf(sub, sizeof sub, "%s %s", own_short[systems[i].owner], sec_short[systems[i].security & 3]);
            int sl = (int) strlen(sub), sx = x - sl * 4;
            if (sx < VIEW_X0) sx = VIEW_X0;
            if (sx + sl * 8 > VIEW_X1) sx = VIEW_X1 - sl * 8;
            text(sx, y + 21, 1, nr * 3 / 4, ng * 3 / 4, nb * 3 / 4, sub);
        }

        /* Each system is a star: a white core in a halo of its owner's colour. */
        int big = zoom == 0 ? 0 : 1;
        if (galaxy_empty(i) && known[i]) {                     /* empty space: a hollow ring, no star */
            gfx_rect(x - 3, y - 3, 6, 1, 0, nr, ng, nb); gfx_rect(x - 3, y + 2, 6, 1, 0, nr, ng, nb);
            gfx_rect(x - 3, y - 3, 1, 6, 0, nr, ng, nb); gfx_rect(x + 2, y - 3, 1, 6, 0, nr, ng, nb);
        } else {
            gfx_rect(x - 1 - big, y - 1 - big, 2 + big * 2, 2 + big * 2, 0, 255, 255, 255);
            gfx_glow(x, y, 5 + big * 3, 5 + big * 3, 0, nr, ng, nb);
            if (zoom) gfx_glow(x, y, 20, 20, 0, nr * 2 / 3, ng * 2 / 3, nb * 2 / 3);
        }
        if (i == sel) {
            gfx_rect(x - 8, y - 8, 4, 2, 0, 255, 230, 80);  gfx_rect(x + 4, y - 8, 4, 2, 0, 255, 230, 80);
            gfx_rect(x - 8, y + 6, 4, 2, 0, 255, 230, 80);  gfx_rect(x + 4, y + 6, 4, 2, 0, 255, 230, 80);
        }
        if (i == current) { int pr = (zoom ? 22 : 12) + ((anim >> 1) & 15); gfx_glow(x, y, pr, pr, 0, 110, 120, 130); }   /* you are here */

        /* Your squadrons and parked ships here (M15a): A B C in gold (! = stranded), H for a docked ship. */
        {
            char marks[8]; int n = 0;
            for (int q = 1; q < SQUADRONS && n < 6; q++)
                if (sq_where(q) == i && sq_order[q] != SQ_MOVE) {
                    marks[n++] = (char) ('A' + q - 1);
                    if (sq_order[q] == SQ_STRANDED) marks[n++] = '!';      /* stranded: no fuel */
                }
            for (int f = 0; f < fleet_count && n < 6; f++)
                if (fleet_sq[f] == 0 && fleet_stance[f] == STANCE_HANGAR && fleet_sys[f] == i) { marks[n++] = 'H'; break; }
            marks[n] = 0;
            if (n && zoom >= 1 && in_view(x + 10 + n * 8, y - 16, 0)) text(x + 10, y - 16, 1, 255, 205, 60, marks);
            else if (n && zoom == 0) gfx_rect(x + 4, y - 7, 3, 3, 0, 255, 205, 60);     /* a gold fleck: ships of yours */
        }
    }

    /* Routes: the plotted course first (so it ends up on top), then dim links. */
    if (route_dest >= 0) {
        int at = current, guard = GALAXY_SYSTEMS;
        while (at != route_dest && guard-- > 0) {
            int n = galaxy_next_hop(at, route_dest);
            if (n < 0) break;
            map_line(at, n, 255, 230, 80);
            at = n;
        }
    }
    for (int i = 0; i < GALAXY_SYSTEMS; i++)
        for (int j = 0; j < systems[i].njumps; j++) {
            int k = systems[i].link[j];
            if (k < i || !visible(i) || !visible(k)) continue;
            map_line(i, k, 60, 80, 120);
        }

    gfx_card(MAP_X0 - 20, card_y, MAP_W + 32, card_h, 0);   /* 40 .. 402, clear of the info card */
    gfx_panel(PANEL_X, PANEL_Y, PANEL_W, PANEL_H, 1);
}
